#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int N;
    cin >> N; // N を読み込む
    vector<int> A(N);
    for (auto &&a : A)
        cin >> a; // A を読み込む

    int min_A = ranges::min(A); // A の最小値を計算

    vector<bool> now_have(N, false); // 今持っている整数を調べる
    for (int a : A)
        now_have[a - min_A] = true; // a - min_A 番目は持っている

    for (int i = 0; i < N; ++i)
        if (!now_have[i]) // 持っていない整数がなくした整数
            cout << i + min_A << endl;

    return 0;
}

#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    int N;
    cin >> N; // N を読み込む
    int min_A = 1000, max_A = 0, xor_A = 0, A; // A の最小値, 最大値, 総 xor
    while (N--) {
        cin >> A;
        min_A = min(A, min_A);
        max_A = max(A, max_A);
        xor_A ^= A;
    }

    ++max_A; // 半開区間にする
    while (max_A % 4 != 0)
        xor_A ^= --max_A; // 全体の xor から [0, max_A + 1) の xor を除く

    while (min_A % 4 != 0)
        xor_A ^= --min_A; // 全体の xor から [0, min_A) の xor を除く

    cout << xor_A << endl;

    return 0;
}
